/**
 * Icons for the docs header and footer on /developers. The tab icons are the
 * Lucide icons the docs tabs use (apps/docs/navigation/en.json `icon`,
 * docs.json `icons.library: "lucide"`), so the 1024-1279px tab row and the
 * mobile menu look like Mintlify's. Lucide is ISC licensed.
 */
import type { ReactNode } from "react";
import type { DocsTabIcon } from "@/data/developers/docs-nav";

function Lucide({
  children,
  size = 16,
  className,
}: {
  children: ReactNode;
  size?: number;
  className?: string;
}) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      focusable="false"
      className={className}
    >
      {children}
    </svg>
  );
}

const TAB_PATHS: Record<DocsTabIcon, ReactNode> = {
  house: (
    <>
      <path d="M15 21v-8a1 1 0 0 0-1-1h-4a1 1 0 0 0-1 1v8" />
      <path d="M3 10a2 2 0 0 1 .709-1.528l7-5.999a2 2 0 0 1 2.582 0l7 5.999A2 2 0 0 1 21 10v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z" />
    </>
  ),
  "credit-card": (
    <>
      <rect width="20" height="14" x="2" y="5" rx="2" />
      <line x1="2" x2="22" y1="10" y2="10" />
    </>
  ),
  layers: (
    <>
      <path d="M12.83 2.18a2 2 0 0 0-1.66 0L2.6 6.08a1 1 0 0 0 0 1.83l8.58 3.91a2 2 0 0 0 1.66 0l8.58-3.9a1 1 0 0 0 0-1.83Z" />
      <path d="m22 17.65-9.17 4.16a2 2 0 0 1-1.66 0L2 17.65" />
      <path d="m22 12.65-9.17 4.16a2 2 0 0 1-1.66 0L2 12.65" />
    </>
  ),
  "chart-line": (
    <>
      <path d="M3 3v16a2 2 0 0 0 2 2h16" />
      <path d="m19 9-5 5-4-4-3 3" />
    </>
  ),
  box: (
    <>
      <path d="M21 8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16Z" />
      <path d="m3.3 7 8.7 5 8.7-5" />
      <path d="M12 22V12" />
    </>
  ),
  wrench: (
    <path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z" />
  ),
  book: (
    <path d="M4 19.5v-15A2.5 2.5 0 0 1 6.5 2H20v20H6.5a2.5 2.5 0 0 1 0-5H20" />
  ),
  play: <polygon points="6 3 20 12 6 21 6 3" />,
};

export function TabIcon({ icon }: { icon: DocsTabIcon }) {
  return <Lucide className="dh-tab-icon">{TAB_PATHS[icon]}</Lucide>;
}

export function SearchIcon({ size = 16 }: { size?: number }) {
  return (
    <Lucide size={size} className="dh-icon">
      <circle cx="11" cy="11" r="8" />
      <path d="m21 21-4.3-4.3" />
    </Lucide>
  );
}

export function ChevronDownIcon() {
  return (
    <Lucide size={12} className="dh-chevron">
      <path d="m6 9 6 6 6-6" />
    </Lucide>
  );
}

export function MenuIcon() {
  return (
    <Lucide size={18} className="dh-icon">
      <line x1="4" x2="20" y1="12" y2="12" />
      <line x1="4" x2="20" y1="6" y2="6" />
      <line x1="4" x2="20" y1="18" y2="18" />
    </Lucide>
  );
}

/** Diagonal "opens in a new tab" arrow (Lucide arrow-up-right). */
export function ExternalArrowIcon({ size = 14 }: { size?: number }) {
  return (
    <Lucide size={size} className="dh-ext">
      <path d="M7 7h10v10" />
      <path d="M7 17 17 7" />
    </Lucide>
  );
}

