export function SocialIcon({ id }: { id: string }) {
  const icon = SOCIAL_ICONS[id];
  if (!icon) return null;
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox={icon.viewBox}
      width="20"
      height="20"
      fill="currentColor"
      aria-hidden="true"
      focusable="false"
    >
      {icon.paths}
    </svg>
  );
}
